compile.workshop:
variables {
    global:
        0: code
        1: g
        2: n
}

//Optimize for size enabled
rule ("operands") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.code == Custom String("");
        Global.code != Custom String("");
        Global.g == Null;
        Global.g == Match Round;
        Global.g == Control Mode Scoring Team;
        Global.g <= Custom String("");
    }
    actions {
        Set Global Variable(n, 2);
    }
}

rule ("reuse") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.code == Custom String("");
    }
    actions {
        While(((Compare(Global.code, ==, Empty Array))));
            Set Global Variable(n, 2);
            Wait(0.5, Ignore Condition);
        End;
    }
}

